#ifndef CORE_PORTME_H
#define CORE_PORTME_H

/* CoreMark configuration for the RV32I three-stage teaching CPU. */
#define HAS_FLOAT       1
#define HAS_TIME_H      0
#define USE_CLOCK       0
#define HAS_STDIO       0
#define HAS_PRINTF      0
#define MAIN_HAS_NOARGC 1
#define MAIN_HAS_NORETURN 0

/* Generated by the build that produced this particular firmware image. */
#include "coremark_build_config.h"

#if !defined(COREMARK_CLOCK_HZ) || !defined(COREMARK_UART_BAUD) || \
    !defined(COREMARK_FORMAL) || !defined(ITERATIONS)
#error "CoreMark requires explicit clock, UART, mode and iterations build definitions"
#endif
#if COREMARK_CLOCK_HZ <= 0 || COREMARK_UART_BAUD <= 0 || \
    COREMARK_UART_BAUD > COREMARK_CLOCK_HZ
#error "Invalid CoreMark clock or UART baud"
#endif
#if COREMARK_FORMAL != 0 && COREMARK_FORMAL != 1
#error "COREMARK_FORMAL must be 0 or 1"
#endif
#if ITERATIONS < 0 || ITERATIONS > 2147483647
#error "ITERATIONS must fit the positive volatile seed type (zero selects auto calibration)"
#endif
#ifndef PERFORMANCE_RUN
#define PERFORMANCE_RUN 0
#endif
#ifndef VALIDATION_RUN
#define VALIDATION_RUN 0
#endif
#if (PERFORMANCE_RUN != 0 && PERFORMANCE_RUN != 1) || \
    (VALIDATION_RUN != 0 && VALIDATION_RUN != 1)
#error "CoreMark run selection flags must be 0 or 1"
#endif
#if (PERFORMANCE_RUN + VALIDATION_RUN) != 1
#error "Select exactly one of PERFORMANCE_RUN=1 and VALIDATION_RUN=1"
#endif

typedef signed short   ee_s16;
typedef unsigned short ee_u16;
typedef signed int     ee_s32;
typedef unsigned int   ee_u32;
typedef unsigned long long ee_u64;
typedef unsigned char  ee_u8;
typedef ee_u32         ee_ptr_int;
typedef ee_u32         ee_size_t;

#ifndef NULL
#define NULL ((void *)0)
#endif

#define align_mem(x) \
    ((void *)(4u + (((ee_ptr_int)(x) - 1u) & ~3u)))

#define CORETIMETYPE ee_u64
typedef ee_u64 CORE_TICKS;

#define SEED_METHOD SEED_VOLATILE
#define MEM_METHOD  MEM_STATIC

#define MULTITHREAD 1
#define USE_PTHREAD 0
#define USE_FORK    0
#define USE_SOCKET  0

extern ee_u32 default_num_contexts;
/* Also available to the focused firmware test through its ELF symbol map. */
extern volatile ee_u32 coremark_actual_iterations;
extern volatile CORE_TICKS coremark_elapsed_ticks;
extern volatile ee_u32 coremark_failed;

typedef struct CORE_PORTABLE_S {
    ee_u8 portable_id;
} core_portable;

void portable_init(core_portable *portable, int *argc, char *argv[]);
void portable_fini(core_portable *portable);
int ee_printf(const char *format, ...);

#endif
